  font-size: var(--vscode-font-size, 13px);
  color: var(--ca-text);
  background: var(--ca-bg);
}

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(77, 141, 255, 0.18);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(77, 141, 255, 0.35);
}

/* ============================================================
   App Shell & Background
   ============================================================ */

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
  position: relative;
  overflow: hidden;
  background: var(--ca-bg);
}

/* The Grainient canvas sits here; keep it behind everything */
.app-bg-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

/* Very subtle dark overlay so the gradient doesn't overpower */
.app-bg-overlay {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(77, 141, 255, 0.06) 0%, transparent 55%),
    linear-gradient(180deg, rgba(9, 11, 16, 0.10) 0%, rgba(9, 11, 16, 0.55) 100%);
  pointer-events: none;
}

/* ============================================================
   Header
   ============================================================ */

.header {
  position: relative;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 42px;
  padding: 0 12px;
  background: rgba(13, 16, 22, 0.95);
  border-bottom: 1px solid var(--ca-border);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  box-shadow: 0 1px 0 rgba(77, 141, 255, 0.04);
  box-sizing: border-box;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 60px;
}

.header-center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
}

.header-brand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
  padding: 4px 8px;
  border-radius: 6px;
  transition: opacity 0.15s ease, background 0.15s ease;
}
.header-brand:hover {
  opacity: 0.9;
