   ============================================================ */

.toolbar {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  max-width: 860px;
  width: 100%;
  align-self: center;
  padding: 0 4px;
}

.dropdown {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  min-width: 0;
}

.dropdown-label {
  color: var(--ca-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 10px;
  font-weight: 650;
  user-select: none;
  line-height: 1;
}

.dropdown-select {
  font-family: inherit;
  font-size: 12px;
  color: var(--ca-text);
  background: var(--ca-surface);
  border: 1px solid var(--ca-border);
