}

/* ============================================================
   Message List
   ============================================================ */

.message-list {
  position: relative;
  z-index: 2;
  flex: 1;
  overflow-y: auto;
  padding: 20px 14px 10px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.message-list > * {
  width: 100%;
  max-width: 860px;
  align-self: center;
}

/* ============================================================
   Empty State — Home Screen
   ============================================================ */

.empty-state {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 32px 18px 24px;
