}

.card-top-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.card-headline {
  font-size: 14px;
  font-weight: 600;
  color: var(--ca-text);
  line-height: 1.25;
  white-space: pre-line;
  letter-spacing: -0.01em;
}

.card-arrow-circle {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 1px solid var(--ca-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ca-muted);
  flex-shrink: 0;
  transition: all 0.18s ease;
  background: var(--ca-surface-raised);
}
.capability-card:hover .card-arrow-circle {
  border-color: var(--ca-accent-border);
  color: var(--ca-accent);
  background: var(--ca-accent-subtle);
  transform: translate(1px, -1px);
}

.card-subtext {
  font-size: 11.5px;
  color: var(--ca-muted);
  line-height: 1.45;
  margin: 0;
}

/* ============================================================
   Messages
   ============================================================ */

.msg {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.msg-avatar {
  flex: none;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  user-select: none;
}

.msg-user .msg-avatar {
  background: var(--ca-surface-raised);
  border: 1px solid var(--ca-border);
  color: var(--ca-text-secondary);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.msg-assistant .msg-avatar {
  background: var(--ca-accent-subtle);
  border: 1px solid var(--ca-accent-border);
  color: var(--ca-accent);
  font-size: 13px;
  box-shadow: 0 0 8px rgba(77, 141, 255, 0.15);
}

.msg-content {
  min-width: 0;
  flex: 1;
  padding-top: 2px;
}

.msg-body {
  line-height: 1.65;
  word-wrap: break-word;
  overflow-wrap: anywhere;
  color: var(--ca-text);
}

.msg-text { white-space: pre-wrap; }
.msg-body p:first-child { margin-top: 0; }
.msg-body p:last-child  { margin-bottom: 0; }
.msg-body p             { margin: 0 0 10px; }

.msg-body pre {
  background: var(--ca-surface);
  border: 1px solid var(--ca-border);
  padding: 12px;
  border-radius: 8px;
  overflow-x: auto;
  margin: 10px 0;
