}

.msg-body :not(pre) > code {
  background: rgba(77, 141, 255, 0.10);
  border: 1px solid rgba(77, 141, 255, 0.20);
  color: var(--ca-accent-soft);
  padding: 1px 6px;
  border-radius: 4px;
}

.msg-body code {
