___CSS_LOADER_EXPORT___.push([module.id, `.grainient-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: hidden;
  background-color: #090B10;
}

.grainient-mesh {
  position: absolute;
  inset: -15%;
  width: 130%;
  height: 130%;
  background:
    radial-gradient(ellipse 60% 45% at 50% 5%, rgba(77, 141, 255, 0.14) 0%, transparent 65%),
    radial-gradient(ellipse 50% 40% at 15% 65%, rgba(42, 91, 191, 0.09) 0%, transparent 60%),
    radial-gradient(ellipse 55% 45% at 85% 85%, rgba(13, 21, 37, 0.85) 0%, transparent 70%),
    #090B10;
  animation: grainientDrift 16s ease-in-out infinite alternate;
}

.grainient-glow-primary {
  position: absolute;
  top: -10%;
  left: 20%;
  width: 380px;
  height: 280px;
  background: radial-gradient(circle, rgba(77, 141, 255, 0.08) 0%, transparent 70%);
  filter: blur(35px);
  animation: grainientPulse 9s ease-in-out infinite alternate;
}

.grainient-glow-secondary {
  position: absolute;
  bottom: 5%;
  right: -5%;
  width: 320px;
  height: 260px;
  background: radial-gradient(circle, rgba(141, 181, 255, 0.06) 0%, transparent 70%);
  filter: blur(30px);
  animation: grainientPulse 13s ease-in-out infinite alternate-reverse;
}

@keyframes grainientDrift {
  0% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-2.5%) scale(1.02); }
  100% { transform: translateY(0) scale(1); }
}

@keyframes grainientPulse {
  0% { opacity: 0.55; transform: scale(0.96); }
  100% { opacity: 0.95; transform: scale(1.08); }
}
